    /// `SYSTEM` follows the phone: Ukrainian when its first language is Ukrainian, otherwise English.
    /// `systemLanguage` is for tests; the app passes nothing.
    public static func resolveLang(_ prefLang: String, systemLanguage: String? = nil) -> String {
        switch prefLang.lowercased() {
        case "uk": return "uk"
        case "en": return "en"
        default:
            let first = Locale.preferredLanguages.first.map { Locale(identifier: $0).language.languageCode?.identifier ?? $0 }
            let sys = (systemLanguage ?? first ?? "en").lowercased()
            return sys == "uk" ? "uk" : "en"
        }
    }

