    /// "2 год", "1 год 30 хв", "45 хв" with non-breaking spaces so a value never splits across lines.
    public static func durationText(_ lang: String, _ totalMinutes: Int) -> String {
        let m = max(0, totalMinutes)
        let h = m / 60
        let mm = m % 60
        let hUnit = lang == "uk" ? "год" : "h"
        let mUnit = lang == "uk" ? "хв" : "min"
        if h > 0 && mm > 0 { return "\(h)\(NBSP)\(hUnit) \(mm)\(NBSP)\(mUnit)" }
        if h > 0 { return "\(h)\(NBSP)\(hUnit)" }
        return "\(mm)\(NBSP)\(mUnit)"
    }

    /// Planned pre-warning (one per merged span). `labels` are the `alertLabels` of the addresses
    /// (spec/SUBSCRIPTIONS.md 8.3); nil keeps the 1.4.0 text.
    public static func plannedAlertBody(
        _ lang: String,
        _ queue: String,
        _ start: String,
        _ end: String,
        _ minutesLeft: Int,
        _ durationMinutes: Int,
        _ mayContinue: Bool,
        labels: String? = nil
    ) -> String {
        let dur = durationText(lang, durationMinutes)
        let uk = lang == "uk"
        let q: String
        if let labels, queue.ktIsBlank || labels == "Черга \(queue)" {
            // a queue-only address is already labelled "Черга 5.2": no second queue in brackets
            q = "\(labels): "
        } else if let labels {
            q = uk ? "\(labels) (черга \(queue)): " : "\(labels) (queue \(queue)): "
        } else if queue.ktIsBlank {
            q = ""
        } else {
            q = uk ? "Черга \(queue): " : "Queue \(queue): "
        }
        let head: String
        if minutesLeft > 0 {
            head = uk ? "\(q)відключення о \(start) (через \(minutesLeft)\(NBSP)хв)" : "\(q)outage at \(start) (in \(minutesLeft)\(NBSP)min)"
        } else {
            head = uk ? "\(q)відключення розпочинається зараз, о \(start)" : "\(q)outage is starting now, at \(start)"
        }
        let tail: String
        if mayContinue {
            tail = uk ? ", орієнтовно до \(end) (\(dur)), можливе продовження." : ", expected until \(end) (\(dur)), may continue."
        } else {
            tail = uk ? ", орієнтовно до \(end) (\(dur))." : ", expected until \(end) (\(dur))."
        }
        return head + tail
    }

    public static func emergencyStartBody(_ lang: String, _ start: String, _ eta: String?) -> String {
