            return lang == "uk" ? "Початок: \(start). Орієнтовне відновлення: \(eta)." : "Start: \(start). Estimated restoration: \(eta)."
        }
        return lang == "uk" ? "Початок: \(start). Час відновлення невідомий." : "Start: \(start). Restoration time unknown."
    }

